#!/usr/bin/env python3
"""Fresh worked-example data and traces, generated by the reference.

exam-prep template verify-examples.py, baseline as of 2026-10-20; changes only via `12-retro`.
Copy it to _build/verify/examples.py and fill the marked part. Run from the hub root:

  python3 -I _build/verify/examples.py      writes _build/verify/examples.out.md

One section per worked example the backbone lists, headed by its id (`## ex-4-ucs: <title>`), with
its inputs and every step and result the notes print. A value the notes need outside a worked
example (a TODO-VERIFY) gets a section of its own, `value-<slug>`, so a rerun reproduces it.
Writers copy from the output and nobody computes a value by hand (FB-090, L50). The inputs are
fresh, never a homework's or a recitation's (FB-071), and each is checked here (solvable, not
degenerate) before its trace prints. Keep it fast: sets and dicts for membership, no quadratic
scans; each section's id goes to stderr as it starts, so a slow one shows; a run that takes
minutes is a bug to fix, not a wait (L51).

The output is replaced only when the run succeeds and has a section for every `ex-` id in
_build/backbone.md, and no `ex-` section the backbone lacks. A failed run (an assert on a bad
input, a missing example) exits 1 and leaves the last good output as it was."""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)  # -I leaves the script dir out
OUT_PATH = os.path.join(HERE, "examples.out.md")
BACKBONE = os.path.join(os.path.dirname(HERE), "backbone.md")
EX_ID = re.compile(r"`(ex-\d+-[\w-]+)`")

SECTIONS = []
_out = None


def emit(text=""):
    _out.write(text + "\n")
    _out.flush()


def section(example_id, title):
    SECTIONS.append(example_id)
    print(example_id, file=sys.stderr, flush=True)
    emit(f"\n## {example_id}: {title}\n")


def row(*cells):
    emit("| " + " | ".join(str(c) for c in cells) + " |")


def examples():
    # ---- Fill in: one block per backbone worked example. ------------------------------------
    # from reference import solve
    # section("ex-4-ucs", "UCS on a six-node graph")
    # graph = {...}
    # result = solve(graph, start="S", tie="alpha")
    # assert result.path, "unsolvable input: pick another"
    # row("Step", "Frontier", "Expanded")
    # row("---", "---", "---")
    # for i, step in enumerate(result.steps, 1):
    #     row(i, step.frontier, step.expanded)
    # emit(f"\n**Result:** path {result.path}, cost {result.cost}")
    pass


def problems():
    """What keeps the output from being replaced."""
    if not SECTIONS:
        return ["NO EXAMPLES: add one section per backbone worked example"]
    if not os.path.isfile(BACKBONE):
        return [f"no {BACKBONE}: the backbone lists the worked examples"]
    with open(BACKBONE, encoding="utf-8") as f:
        want = set(EX_ID.findall(f.read()))
    out = [f"MISSING {i}: the backbone lists it" for i in sorted(want - set(SECTIONS))]
    out += [f"NOT IN THE BACKBONE {i}" for i in sorted({s for s in SECTIONS if s.startswith("ex-")}
                                                       - want)]
    out += [f"TWICE {i}" for i in sorted({s for s in SECTIONS if SECTIONS.count(s) > 1})]
    return out


def main():
    global _out
    tmp = OUT_PATH + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as _out:
            emit("# Worked examples (generated by examples.py: rerun it, never edit this file)")
            examples()
        bad = problems()
        if bad:
            for b in bad:
                print(f"examples.py: {b}", file=sys.stderr)
            print("examples.py: examples.out.md not replaced", file=sys.stderr)
            return 1
        os.replace(tmp, OUT_PATH)
        print(f"examples.py: wrote examples.out.md, {len(SECTIONS)} sections", file=sys.stderr)
        return 0
    finally:
        if os.path.exists(tmp):
            os.remove(tmp)


if __name__ == "__main__":
    sys.exit(main())
